IvPFunction* BHV_GoPoint::onRunState()
{
  // 1. Safely retrieve data from the InfoBuffer
  bool ok1, ok2;
  double osx = getBufferDoubleVal("NAV_X", ok1);
  double osy = getBufferDoubleVal("NAV_Y", ok2);
  if(!ok1 || !ok2) 
    return nullptr; // Not active if data is missing [15]

  // 2. Calculate the desired setpoint
  double target_heading = relAng(osx, osy, m_ptx, m_pty);

  // 3. Build a 1D IvPFunction for Heading (Course) [12, 13]
  ZAIC_PEAK crs_zaic(m_domain, "course");
  crs_zaic.setSummit(target_heading);
  crs_zaic.setPeakWidth(0);
  crs_zaic.setBaseWidth(180.0);
  crs_zaic.setSummitDelta(0);  
  IvPFunction *crs_ipf = crs_zaic.extractIvPFunction();

  // 4. Build a 1D IvPFunction for Speed [12, 13]
  ZAIC_PEAK spd_zaic(m_domain, "speed");
  spd_zaic.setSummit(m_speed);
  spd_zaic.setPeakWidth(0.5);
  spd_zaic.setBaseWidth(1.0);
  IvPFunction *spd_ipf = spd_zaic.extractIvPFunction();

