  int vindex = m_domain.getVarIndex("speed");
  if(vindex == -1) {
    postEMessage("Variable 'speed' not found in helm domain.");
    return nullptr;
  }

  // 2. Initialize ZAIC_PEAK with the domain and variable index
  ZAIC_PEAK spd_zaic(m_domain, vindex);

  // 3. Configure the function shape (peak and base widths)
  spd_zaic.setSummit(m_speed);
  spd_zaic.setPeakWidth(0.5);   // Utility is 100 within +/- 0.5 m/s
